BEGIN;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM hospital_admission_importing_logs
    WHERE tenant_id = 136
      AND ff1_file_name = '産婦人科様式1なし_2608.txt'
  ) THEN
    RAISE EXCEPTION 'already imported: 産婦人科様式1なし_2608.txt';
  END IF;
